//@ run-pass
//@ expect-stdout: CRANELIFT_GEO_MIN_PASS
// Minimal reproducer for a Cranelift 16-lane Clifford-style geometric
// product accumulation pattern that regressed in the past.
//
// Expected behavior:
// - `souc run` (self-hosted VM) prints CRANELIFT_GEO_MIN_PASS
// - `souc jit` should also print CRANELIFT_GEO_MIN_PASS
//
// This fixture stays in run-pass as a backend parity regression guard.

fn abs_f64(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn approx_eq(a: f64, b: f64, tol: f64) -> bool {
    abs_f64(a - b) < tol
}

fn geo_sign(a: i64, b: i64) -> f64 with Mut, Panic, Div {
    var swaps = 0
    var j = 0
    while j < 4 {
        if (b >> j) & 1 != 0 {
            var k = j + 1
            while k < 4 {
                if (a >> k) & 1 != 0 { swaps = swaps + 1 }
                k = k + 1
            }
        }
        j = j + 1
    }
    let common = a & b
    var msign = 1.0
    if (common >> 1) & 1 != 0 { msign = 0.0 - msign }
    if (common >> 2) & 1 != 0 { msign = 0.0 - msign }
    if (common >> 3) & 1 != 0 { msign = 0.0 - msign }
    if swaps % 2 == 0 { return msign }
    return 0.0 - msign
}

fn geo_product(a: [f64], b: [f64]) -> [f64] with Mut, Panic, Div {
    var r0  = 0.0; var r1  = 0.0; var r2  = 0.0; var r3  = 0.0
    var r4  = 0.0; var r5  = 0.0; var r6  = 0.0; var r7  = 0.0
    var r8  = 0.0; var r9  = 0.0; var r10 = 0.0; var r11 = 0.0
    var r12 = 0.0; var r13 = 0.0; var r14 = 0.0; var r15 = 0.0
    var i = 0
    while i < 16 {
        if a[i] != 0.0 {
            var j = 0
            while j < 16 {
                if b[j] != 0.0 {
                    let k = i ^ j
                    let val = geo_sign(i, j) * a[i] * b[j]
                    if k == 0 { r0 = r0 + val }
                    else if k == 1 { r1 = r1 + val }
                    else if k == 2 { r2 = r2 + val }
                    else if k == 3 { r3 = r3 + val }
                    else if k == 4 { r4 = r4 + val }
                    else if k == 5 { r5 = r5 + val }
                    else if k == 6 { r6 = r6 + val }
                    else if k == 7 { r7 = r7 + val }
                    else if k == 8 { r8 = r8 + val }
                    else if k == 9 { r9 = r9 + val }
                    else if k == 10 { r10 = r10 + val }
                    else if k == 11 { r11 = r11 + val }
                    else if k == 12 { r12 = r12 + val }
                    else if k == 13 { r13 = r13 + val }
                    else if k == 14 { r14 = r14 + val }
                    else if k == 15 { r15 = r15 + val }
                }
                j = j + 1
            }
        }
        i = i + 1
    }
    return [r0, r1, r2, r3, r4, r5, r6, r7,
            r8, r9, r10, r11, r12, r13, r14, r15]
}

fn mv_basis(idx: i64) -> [f64] with Mut, Panic, Div {
    var r0  = 0.0; var r1  = 0.0; var r2  = 0.0; var r3  = 0.0
    var r4  = 0.0; var r5  = 0.0; var r6  = 0.0; var r7  = 0.0
    var r8  = 0.0; var r9  = 0.0; var r10 = 0.0; var r11 = 0.0
    var r12 = 0.0; var r13 = 0.0; var r14 = 0.0; var r15 = 0.0
    if idx == 0 { r0 = 1.0 }
    else if idx == 1 { r1 = 1.0 }
    else if idx == 2 { r2 = 1.0 }
    else if idx == 3 { r3 = 1.0 }
    else if idx == 4 { r4 = 1.0 }
    else if idx == 5 { r5 = 1.0 }
    else if idx == 6 { r6 = 1.0 }
    else if idx == 7 { r7 = 1.0 }
    else if idx == 8 { r8 = 1.0 }
    else if idx == 9 { r9 = 1.0 }
    else if idx == 10 { r10 = 1.0 }
    else if idx == 11 { r11 = 1.0 }
    else if idx == 12 { r12 = 1.0 }
    else if idx == 13 { r13 = 1.0 }
    else if idx == 14 { r14 = 1.0 }
    else if idx == 15 { r15 = 1.0 }
    return [r0, r1, r2, r3, r4, r5, r6, r7,
            r8, r9, r10, r11, r12, r13, r14, r15]
}

fn test_full_metric() -> bool with Mut, Panic, Div {
    let e0_sq = geo_product(mv_basis(1), mv_basis(1))
    let e1_sq = geo_product(mv_basis(2), mv_basis(2))
    let e2_sq = geo_product(mv_basis(4), mv_basis(4))
    let e3_sq = geo_product(mv_basis(8), mv_basis(8))
    return approx_eq(e0_sq[0], 1.0, 1.0e-10)
        && approx_eq(e1_sq[0], 0.0 - 1.0, 1.0e-10)
        && approx_eq(e2_sq[0], 0.0 - 1.0, 1.0e-10)
        && approx_eq(e3_sq[0], 0.0 - 1.0, 1.0e-10)
}

fn main() -> i32 with IO, Mut, Panic, Div {
    if test_full_metric() {
        println("CRANELIFT_GEO_MIN_PASS")
        return 0
    }
    println("CRANELIFT_GEO_MIN_FAIL")
    return 1
}

//@ run-pass
//@ timeout: 90
// Proves the ω² (IIV) and u_c (epistemic GUM) axes are INDEPENDENT in the nested
// population×epistemic layer (pop_epistemic.sio), and that u_c→0 collapses to the
// flat virtual-population semantics (backward compatibility).
//
// Because sample_normal consumes the RNG independently of (mean, sd), the same
// seed gives an identical standard-normal stream across configs, so the
// separation is EXACT (cross-effects vanish to f64 round-off), not statistical:
//   · varying ω  changes the IIV P95/P5 ratio but NOT the epistemic median CV
//   · varying u_c changes the epistemic median CV but NOT the IIV P95/P5 ratio

use darwin_pbpk::population::pop_epistemic::{pop_epistemic_run, PopEpiResult}

fn sabs(x: f64) -> f64 { if x < 0.0 { 0.0 - x } else { x } }

fn main() -> i32 with IO, Mut, Div, Panic {
    println("Nested population × epistemic separation — pop_epistemic.sio")
    println("")

    let cl = 12.4      // rapamycin population CL (L/h)
    let dose = 5.0
    let f = 1.0        // IV
    let M = 200        // epistemic draws
    let N = 64         // individuals per population
    let seed = 42

    // Four configs sharing the SAME seed → identical standard-normal stream.
    let base = pop_epistemic_run(cl, 0.20, 0.30, M, N, dose, f, seed) // u_c=0.20, ω=0.30
    let om2  = pop_epistemic_run(cl, 0.20, 0.60, M, N, dose, f, seed) // ω doubled
    let uc2  = pop_epistemic_run(cl, 0.40, 0.30, M, N, dose, f, seed) // u_c doubled
    let coll = pop_epistemic_run(cl, 0.00, 0.30, M, N, dose, f, seed) // u_c → 0

    print("base : median="); print(base.median_pop); print(" iiv_ratio="); print(base.iiv_ratio); print(" epi_cv%="); println(base.epi_cv)
    print("ω×2  : median="); print(om2.median_pop);  print(" iiv_ratio="); print(om2.iiv_ratio);  print(" epi_cv%="); println(om2.epi_cv)
    print("u_c×2: median="); print(uc2.median_pop);  print(" iiv_ratio="); print(uc2.iiv_ratio);  print(" epi_cv%="); println(uc2.epi_cv)
    print("u_c=0: median="); print(coll.median_pop); print(" iiv_ratio="); print(coll.iiv_ratio); print(" epi_cv%="); println(coll.epi_cv)
    println("")

    let eps = 1.0e-6

    // SEPARATION — cross-effects must vanish:
    //  (a) doubling ω leaves the epistemic median CV unchanged
    let sep_a = sabs(om2.epi_cv - base.epi_cv) < eps
    //  (b) doubling u_c leaves the IIV P95/P5 ratio unchanged
    let sep_b = sabs(uc2.iiv_ratio - base.iiv_ratio) < eps
    // DIRECT effects — each knob moves its OWN axis:
    //  (c) doubling u_c grows the epistemic median CV (>1.5×)
    let dir_c = uc2.epi_cv > base.epi_cv * 1.5
    //  (d) doubling ω widens the IIV P95/P5 ratio (>1.5×)
    let dir_d = om2.iiv_ratio > base.iiv_ratio * 1.5

    print("  (a) ω⊥epistemic   |Δepi_cv|="); print(sabs(om2.epi_cv - base.epi_cv)); if sep_a { println("  OK") } else { println("  FAIL") }
    print("  (b) u_c⊥IIV       |Δiiv_ratio|="); print(sabs(uc2.iiv_ratio - base.iiv_ratio)); if sep_b { println("  OK") } else { println("  FAIL") }
    print("  (c) u_c→epi_cv    ratio="); print(uc2.epi_cv / base.epi_cv); if dir_c { println("  OK") } else { println("  FAIL") }
    print("  (d) ω→iiv_ratio   ratio="); print(om2.iiv_ratio / base.iiv_ratio); if dir_d { println("  OK") } else { println("  FAIL") }
    println("")

    if sep_a && sep_b && dir_c && dir_d {
        println("POP_EPISTEMIC_SEPARATION_PASS")
    } else {
        println("POP_EPISTEMIC_SEPARATION_FAIL")
    }

    // COLLAPSE — u_c→0 ⇒ negligible epistemic band (single population = baseline),
    // and the IIV interval is unchanged from base (same ω). epi_cv is a PERCENT;
    // u_c=0 drives it to the numerical floor (~1e-3 %), a >1000× collapse from the
    // base 20.9% — i.e. the epistemic band vanishes, recovering flat PopSim.
    let coll_epi_zero = coll.epi_cv < 0.01 && coll.epi_cv < base.epi_cv * 0.001
    let coll_iiv_same = sabs(coll.iiv_ratio - base.iiv_ratio) < eps
    print("  u_c=0 epi_cv≈0 (% , floor): "); print(coll.epi_cv); if coll_epi_zero { println("  OK") } else { println("  FAIL") }
    print("  u_c=0 IIV==base: |Δ|="); print(sabs(coll.iiv_ratio - base.iiv_ratio)); if coll_iiv_same { println("  OK") } else { println("  FAIL") }
    if coll_epi_zero && coll_iiv_same {
        println("POP_EPISTEMIC_COLLAPSE_TO_BASELINE_PASS")
    } else {
        println("POP_EPISTEMIC_COLLAPSE_TO_BASELINE_FAIL")
    }

    return 0
}

//@ run-pass
// DataFrame dense storage — run-pass test
//
// T1: Create DF, set/get values
// T2: Column mean/std
// T3: Filter keeps only matching rows
// T4: Sort orders correctly
//
// All helpers inlined — tests cannot import stdlib.

extern "C" {
    fn sqrt(x: f64) -> f64
}

fn t_sqrt(x: f64) -> f64 {
    if x <= 0.0 { return 0.0 }
    return sqrt(x)
}

fn t_abs(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

// ============================================================================
// INLINE DATAFRAME (mirrors stdlib/data/dataframe.sio)
// ============================================================================

struct DataFrame {
    data: [f64; 65536],
    col_names: [i64; 64],
    n_rows: i64,
    n_cols: i64,
}

fn df_new(n_cols: i64) -> DataFrame with Mut {
    var nc = n_cols
    if nc < 0 { nc = 0 }
    if nc > 64 { nc = 64 }
    DataFrame {
        data: [0.0; 65536],
        col_names: [0; 64],
        n_rows: 0,
        n_cols: nc,
    }
}

fn df_set(df: &!DataFrame, row: i64, col: i64, val: f64) with Mut, Panic {
    if row < 0 { return }
    if col < 0 { return }
    if row >= df.n_rows { return }
    if col >= df.n_cols { return }
    let idx = row * 64 + col
    df.data[idx] = val
}

fn df_get(df: &DataFrame, row: i64, col: i64) -> f64 with Panic {
    if row < 0 { return 0.0 }
    if col < 0 { return 0.0 }
    if row >= df.n_rows { return 0.0 }
    if col >= df.n_cols { return 0.0 }
    let idx = row * 64 + col
    return df.data[idx]
}

fn df_add_row(df: &!DataFrame, values: &[f64; 64]) with Mut, Div, Panic {
    if df.n_rows >= 1024 { return }
    let row = df.n_rows
    var col: i64 = 0
    while col < df.n_cols {
        let idx = row * 64 + col
        df.data[idx] = values[col]
        col = col + 1
    }
    df.n_rows = df.n_rows + 1
}

fn df_col_mean(df: &DataFrame, col: i64) -> f64 with Mut, Div, Panic {
    if col < 0 { return 0.0 }
    if col >= df.n_cols { return 0.0 }
    if df.n_rows == 0 { return 0.0 }
    var sum = 0.0
    var row: i64 = 0
    while row < df.n_rows {
        sum = sum + df.data[row * 64 + col]
        row = row + 1
    }
    return sum / (df.n_rows as f64)
}

fn df_col_std(df: &DataFrame, col: i64) -> f64 with Mut, Div, Panic {
    if col < 0 { return 0.0 }
    if col >= df.n_cols { return 0.0 }
    if df.n_rows < 2 { return 0.0 }
    let mean = df_col_mean(df, col)
    var sum_sq = 0.0
    var row: i64 = 0
    while row < df.n_rows {
        let diff = df.data[row * 64 + col] - mean
        sum_sq = sum_sq + diff * diff
        row = row + 1
    }
    let variance = sum_sq / ((df.n_rows - 1) as f64)
    return t_sqrt(variance)
}

fn df_col_min(df: &DataFrame, col: i64) -> f64 with Mut, Div, Panic {
    if col < 0 { return 0.0 }
    if col >= df.n_cols { return 0.0 }
    if df.n_rows == 0 { return 0.0 }
    var m = df.data[0 * 64 + col]
    var row: i64 = 1
    while row < df.n_rows {
        let v = df.data[row * 64 + col]
        if v < m { m = v }
        row = row + 1
    }
    return m
}

fn df_col_max(df: &DataFrame, col: i64) -> f64 with Mut, Div, Panic {
    if col < 0 { return 0.0 }
    if col >= df.n_cols { return 0.0 }
    if df.n_rows == 0 { return 0.0 }
    var m = df.data[0 * 64 + col]
    var row: i64 = 1
    while row < df.n_rows {
        let v = df.data[row * 64 + col]
        if v > m { m = v }
        row = row + 1
    }
    return m
}

fn df_filter_gt(df: &DataFrame, col: i64, threshold: f64) -> DataFrame with Mut, Div, Panic {
    var result = df_new(df.n_cols)
    if col < 0 { return result }
    if col >= df.n_cols { return result }
    var row: i64 = 0
    while row < df.n_rows {
        let v = df.data[row * 64 + col]
        if v > threshold {
            if result.n_rows < 1024 {
                let dst_row = result.n_rows
                var c: i64 = 0
                while c < df.n_cols {
                    result.data[dst_row * 64 + c] = df.data[row * 64 + c]
                    c = c + 1
                }
                result.n_rows = result.n_rows + 1
            }
        }
        row = row + 1
    }
    return result
}

fn df_sort_by(df: &DataFrame, col: i64) -> DataFrame with Mut, Div, Panic {
    var result = df_new(df.n_cols)
    if col < 0 { return result }
    if col >= df.n_cols { return result }
    var row: i64 = 0
    while row < df.n_rows {
        var c: i64 = 0
        while c < df.n_cols {
            result.data[row * 64 + c] = df.data[row * 64 + c]
            c = c + 1
        }
        row = row + 1
    }
    result.n_rows = df.n_rows
    // Insertion sort ascending
    var i: i64 = 1
    while i < result.n_rows {
        let key_val = result.data[i * 64 + col]
        var j = i - 1
        while j >= 0 {
            let cmp_val = result.data[j * 64 + col]
            if cmp_val > key_val {
                var c2: i64 = 0
                while c2 < result.n_cols {
                    let tmp = result.data[(j + 1) * 64 + c2]
                    result.data[(j + 1) * 64 + c2] = result.data[j * 64 + c2]
                    result.data[j * 64 + c2] = tmp
                    c2 = c2 + 1
                }
                j = j - 1
            } else {
                j = -1
            }
        }
        i = i + 1
    }
    return result
}

