    println("; color: #e0e0e0; font-family: sans-serif; }")
    println("  canvas { border: 1px solid #333; cursor: grab; }")
    println("</style>")
    println("</head>")
    println("<body>")
    print("<h1>")
    print(config.title)
    println("</h1>")
    print("<canvas id=\"c\" width=\"")
    p3d_print_int(config.width)
    print("\" height=\"")
    p3d_print_int(config.height)
    println("\"></canvas>")
    println("<script>")
}

fn p3d_emit_html_footer() with IO {
    println("</script>")
    println("</body>")
    println("</html>")
}

fn p3d_emit_js_engine(config: &Plot3DConfig) with IO, Mut, Panic, Div {
    println("'use strict';")
    println("const canvas = document.getElementById('c');")
    println("const ctx = canvas.getContext('2d');")
    println("const W = canvas.width, H = canvas.height;")
    println("const cx = W / 2, cy = H / 2;")
    println("const scale = Math.min(W, H) * 0.32;")
    print("let rotX = ")
    p3d_print_f64(config.camera_angle_x, 4)
    println(";")
    print("let rotY = ")
    p3d_print_f64(config.camera_angle_y, 4)
    println(";")
    println("let zoom = 1.0;")
    println("function project(x, y, z) {")
    println("  const cosX = Math.cos(rotX), sinX = Math.sin(rotX);")
    println("  const cosY = Math.cos(rotY), sinY = Math.sin(rotY);")
    println("  const y1 = y * cosX - z * sinX;")
    println("  const z1 = y * sinX + z * cosX;")
    println("  const x1 = x * cosY + z1 * sinY;")
    println("  const z2 = -x * sinY + z1 * cosY;")
    println("  const s = scale * zoom * (1.0 + z2 * 0.15);")
    println("  return { px: cx + x1 * s, py: cy - y1 * s, depth: z2 };")
    println("}")
    println("function drawAxes() {")
    println("  const o = project(0,0,0);")
    println("  [[1.1,0,0,'#ff6b6b'],[0,1.1,0,'#51cf66'],[0,0,1.1,'#339af0']].forEach(a => {")
    println("    const e = project(a[0],a[1],a[2]);")
    println("    ctx.beginPath(); ctx.moveTo(o.px,o.py); ctx.lineTo(e.px,e.py);")
    println("    ctx.strokeStyle = a[3]; ctx.lineWidth = 1.5; ctx.stroke();")
    println("  });")
    println("}")
    println("let dragging = false, lastMX = 0, lastMY = 0;")
    println("canvas.addEventListener('mousedown', e => { dragging = true; lastMX = e.clientX; lastMY = e.clientY; });")
    println("canvas.addEventListener('mouseup', () => dragging = false);")
    println("canvas.addEventListener('mousemove', e => {")
    println("  if (!dragging) return;")
    println("  rotY += (e.clientX - lastMX) * 0.008;")
    println("  rotX += (e.clientY - lastMY) * 0.008;")
    println("  lastMX = e.clientX; lastMY = e.clientY; render();")
    println("});")
    println("canvas.addEventListener('wheel', e => { e.preventDefault(); zoom *= e.deltaY > 0 ? 0.92 : 1.08; zoom = Math.max(0.2, Math.min(5, zoom)); render(); }, {passive:false});")
}

fn p3d_emit_scatter_data(data: &Scatter3D) with IO, Mut, Panic, Div {
    if data.n <= 0 { return }
    var x_min = data.x[0]
    var x_max = data.x[0]
    var y_min = data.y[0]
    var y_max = data.y[0]
    var z_min = data.z[0]
    var z_max = data.z[0]
    var i: i64 = 1
    while i < data.n {
        if data.x[i as usize] < x_min { x_min = data.x[i as usize] }
        if data.x[i as usize] > x_max { x_max = data.x[i as usize] }
        if data.y[i as usize] < y_min { y_min = data.y[i as usize] }
        if data.y[i as usize] > y_max { y_max = data.y[i as usize] }
        if data.z[i as usize] < z_min { z_min = data.z[i as usize] }
        if data.z[i as usize] > z_max { z_max = data.z[i as usize] }
        i = i + 1
    }
    let x_range = if x_max > x_min { x_max - x_min } else { 1.0 }
    let y_range = if y_max > y_min { y_max - y_min } else { 1.0 }
    let z_range = if z_max > z_min { z_max - z_min } else { 1.0 }
    println("const scatterPts = [")
    i = 0
    while i < data.n {
        let nx = (data.x[i as usize] - x_min) / x_range * 2.0 - 1.0
        let ny = (data.y[i as usize] - y_min) / y_range * 2.0 - 1.0
        let nz = (data.z[i as usize] - z_min) / z_range * 2.0 - 1.0
        print("  [")
        p3d_print_f64(nx, 4)
        print(",")
        p3d_print_f64(ny, 4)
        print(",")
        p3d_print_f64(nz, 4)
        print("]")
        if i < data.n - 1 { print(",") }
        println("")
        i = i + 1
    }
    println("];")
    print("const scatterColor = '")
    print(data.color)
    println("';")
    print("const scatterSize = ")
    p3d_print_f64(data.point_size, 1)
    println(";")
}

fn p3d_emit_scatter_render() with IO, Mut {
    println("function drawScatter() {")
    println("  if (typeof scatterPts === 'undefined') return;")
    println("  const projected = scatterPts.map(p => {")
    println("    const pr = project(p[0], p[1], p[2]);")
    println("    return { px: pr.px, py: pr.py, depth: pr.depth };")
    println("  });")
    println("  projected.sort((a, b) => a.depth - b.depth);")
    println("  projected.forEach(p => {")
    println("    const r = scatterSize * (1.0 + p.depth * 0.3);")
    println("    ctx.beginPath();")
    println("    ctx.arc(p.px, p.py, Math.max(1, r), 0, Math.PI * 2);")
    println("    ctx.fillStyle = scatterColor;")
    println("    ctx.globalAlpha = 0.5 + 0.5 * ((p.depth + 1.5) / 3.0);")
    println("    ctx.fill();")
    println("  });")
    println("  ctx.globalAlpha = 1.0;")
    println("}")
}

fn p3d_emit_surface_data(surf: &Surface3D) with IO, Mut, Panic, Div {
    if surf.nx <= 0 || surf.ny <= 0 { return }
    var z_min = surf.z_grid[0]
    var z_max = surf.z_grid[0]
    var idx: i64 = 1
    let total = surf.nx * surf.ny
    while idx < total {
        if idx < 4096 {
            if surf.z_grid[idx as usize] < z_min { z_min = surf.z_grid[idx as usize] }
            if surf.z_grid[idx as usize] > z_max { z_max = surf.z_grid[idx as usize] }
        }
        idx = idx + 1
    }
    let z_range = if z_max > z_min { z_max - z_min } else { 1.0 }
    print("const surfNX = ")
    p3d_print_int(surf.nx)
    print(", surfNY = ")
    p3d_print_int(surf.ny)
    println(";")
    println("const surfGrid = [")
    var iy: i64 = 0
    while iy < surf.ny {
        print("  [")
        var ix: i64 = 0
        while ix < surf.nx {
            let gi = iy * surf.nx + ix
            let nx = if surf.nx > 1 { ix as f64 / (surf.nx - 1) as f64 * 2.0 - 1.0 } else { 0.0 }
            let ny = if surf.ny > 1 { iy as f64 / (surf.ny - 1) as f64 * 2.0 - 1.0 } else { 0.0 }
            let nz = if gi < 4096 { (surf.z_grid[gi as usize] - z_min) / z_range * 2.0 - 1.0 } else { 0.0 }
            print("[")
            p3d_print_f64(nx, 4)
            print(",")
            p3d_print_f64(ny, 4)
            print(",")
            p3d_print_f64(nz, 4)
            print("]")
            if ix < surf.nx - 1 { print(",") }
            ix = ix + 1
        }
        print("]")
        if iy < surf.ny - 1 { print(",") }
        println("")
        iy = iy + 1
    }
    println("];")
}

fn p3d_emit_surface_render() with IO, Mut {
    println("function drawSurface() {")
    println("  if (typeof surfGrid === 'undefined') return;")
    println("  for (let iy = 0; iy < surfNY; iy++) {")
    println("    for (let ix = 0; ix < surfNX; ix++) {")
    println("      const pt = surfGrid[iy][ix];")
    println("      const p0 = project(pt[0], pt[2], pt[1]);")
    println("      if (ix < surfNX - 1) {")
    println("        const pt1 = surfGrid[iy][ix+1];")
    println("        const p1 = project(pt1[0], pt1[2], pt1[1]);")
    println("        const h = (pt[2]+1)/2;")
    println("        ctx.strokeStyle = 'rgba('+ Math.floor(40+180*h) +','+ Math.floor(150-50*h) +','+ Math.floor(200-100*h) +',0.6)';")
    println("        ctx.lineWidth = 0.8;")
    println("        ctx.beginPath(); ctx.moveTo(p0.px,p0.py); ctx.lineTo(p1.px,p1.py); ctx.stroke();")
    println("      }")
    println("      if (iy < surfNY - 1) {")
    println("        const pt2 = surfGrid[iy+1][ix];")
    println("        const p2 = project(pt2[0], pt2[2], pt2[1]);")
    println("        const h = (pt[2]+1)/2;")
    println("        ctx.strokeStyle = 'rgba('+ Math.floor(40+180*h) +','+ Math.floor(150-50*h) +','+ Math.floor(200-100*h) +',0.6)';")
    println("        ctx.lineWidth = 0.8;")
    println("        ctx.beginPath(); ctx.moveTo(p0.px,p0.py); ctx.lineTo(p2.px,p2.py); ctx.stroke();")
    println("      }")
    println("    }")
    println("  }")
    println("}")
}

fn p3d_emit_render_scatter() with IO, Mut {
    println("function render() {")
    println("  ctx.fillStyle = '#1a1a2e';")
    println("  ctx.fillRect(0, 0, W, H);")
