//@ run-pass
// GENERAL 16-component Cayley-Dickson product over Q -- ALL 16 components, ARBITRARY rational
// coefficients (not just the canonical +/-1 channel). Key: the common-denominator representation
// (a rational sedenion = 16 integer numerators A[16] over one common denom Ad) reduces the rational
// 16-comp product to an INTEGER 16-comp product of numerators, den = Ad*Bd -- so NO [Rational;16]
// by-value aggregate (the #637 wall is CIRCUMVENTED, not hit). v1: i64 numerators (rational coeffs
// with num/den up to ~1e8; output fits i64). Cross-verified element-wise vs scripts/research/cd16_oracle.py.
// Bigint numerators (unbounded coeffs) is the next step. Emits DEN/COMP lines for the gate.
// numerators A[16] over a common denom Ad. (a*b)[k] = (sum_{i^j=k} sigma(i,j) A[i] B[j]) / (Ad*Bd).
// So the rational 16-comp product reduces to an INTEGER 16-comp product of numerators. v1: i64.
fn cd_sigma_c(a: i64, b: i64, bits: i64) -> i64 with Mut, Panic, Div {
    if a == 0 || b == 0 { return 1 }
    if bits <= 1 { return 0 - 1 }
    let half = 1 << (bits - 1)
    let a_hi = if a >= half { 1 } else { 0 }
    let b_hi = if b >= half { 1 } else { 0 }
    let a_lo = a & (half - 1)
    let b_lo = b & (half - 1)
    if a_hi == 0 && b_hi == 0 { return cd_sigma_c(a_lo, b_lo, bits - 1) }
    if a_hi == 0 && b_hi == 1 { return cd_sigma_c(b_lo, a_lo, bits - 1) }
    if a_hi == 1 && b_hi == 0 {
        if b_lo == 0 { return cd_sigma_c(a_lo, 0, bits - 1) }
        return 0 - cd_sigma_c(a_lo, b_lo, bits - 1)
    }
    if b_lo == 0 { return 0 - cd_sigma_c(0, a_lo, bits - 1) }
    cd_sigma_c(b_lo, a_lo, bits - 1)
}
// full 16-component integer-numerator product, emits COMP k <num> ; common denom printed as DEN <ad*bd>
fn cd16(tag: i64, an: [i64; 16], ad: i64, bn: [i64; 16], bd: i64) with IO, Mut, Panic, Div {
    var out = [0; 16]
    var i = 0
    while i < 16 {
        if an[i as usize] != 0 {
            var j = 0
            while j < 16 {
                if bn[j as usize] != 0 {
                    let k = i ^ j
                    let s = cd_sigma_c(i, j, 4)
                    out[k as usize] = out[k as usize] + s * an[i as usize] * bn[j as usize]
                }
                j = j + 1
            }
        }
        i = i + 1
    }
    print("DEN "); print_int(tag); print(" "); print_int(ad * bd); print("\n")
    var m = 0
    while m < 16 {
        print("COMP "); print_int(tag); print(" "); print_int(m); print(" "); print_int(out[m as usize]); print("\n")
        m = m + 1
    }
}
fn main() with IO, Mut, Panic, Div {
    // Case 1 canonical: a=e3+e10 (Ad=1), b=e6-e15 (Bd=1). Expect all 16 COMP = 0.
