fn sum(s: &[f64]) -> f64 with Mut {
    var i = 0
    var acc = 0.0
    while i < s.len() {
        acc = acc + s[i]
        i = i + 1
    }
    return acc
}

fn swap(s: &![f64], i: i64, j: i64) with Mut {
    let tmp = s[i]
    s[i] = s[j]
    s[j] = tmp
}

